<?php
declare(strict_types=1);
require_once __DIR__ . '/bootstrap.php';
$page_title = 'LensCraft | Your Story, Beautifully Captured';
$featured = [];
$portfolio = [];
$counts = ['photographers'=>0,'packages'=>0];
try {
    $rs = db()->query("SELECT p.id,p.studio_name,p.category,p.location,p.bio,p.cover_url,p.avatar_url,p.rating,p.base_price, MIN(pa.price) AS min_price, COUNT(DISTINCT pa.id) AS package_count FROM photographers p LEFT JOIN packages pa ON pa.photographer_id=p.id AND pa.is_active=1 AND pa.stock_qty>0 WHERE p.is_active=1 GROUP BY p.id,p.studio_name,p.category,p.location,p.bio,p.cover_url,p.avatar_url,p.rating,p.base_price ORDER BY p.rating DESC,p.id DESC LIMIT 6");
    while ($row = $rs->fetch_assoc()) $featured[] = $row;
    $rs = db()->query("SELECT pi.image_path,pi.caption,p.id AS photographer_id,p.studio_name,p.category FROM portfolio_images pi JOIN photographers p ON p.id=pi.photographer_id WHERE p.is_active=1 ORDER BY pi.created_at DESC,pi.id DESC LIMIT 8");
    while ($row = $rs->fetch_assoc()) $portfolio[] = $row;
    $counts['photographers'] = (int) db()->query("SELECT COUNT(*) n FROM photographers WHERE is_active=1")->fetch_assoc()['n'];
    $counts['packages'] = (int) db()->query("SELECT COUNT(*) n FROM packages pa JOIN photographers p ON p.id=pa.photographer_id WHERE p.is_active=1 AND pa.is_active=1 AND pa.stock_qty>0")->fetch_assoc()['n'];
} catch (Throwable $ex) {
    error_log('Home page data error: '.$ex->getMessage());
}
$categories = [
